alter table public.expenses add column if not exists voided_at timestamptz, add column if not exists void_reason text;
create table if not exists public.expense_payments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, expense_id uuid not null references public.expenses(id) on delete cascade, payment_date date not null default current_date, currency public.currency_code not null, amount numeric(14,2) not null check(amount>0), fx_crc_per_usd_snapshot numeric(14,4), external_reference text, notes text, status text not null default 'paid' check(status in ('paid','voided')), void_reason text, voided_at timestamptz, created_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists expense_payments_org_expense_idx on public.expense_payments(organization_id,expense_id);
alter table public.expense_payments enable row level security;
drop policy if exists expense_payments_member_all on public.expense_payments;
create policy expense_payments_member_all on public.expense_payments for all using (exists(select 1 from public.organization_members om where om.organization_id=expense_payments.organization_id and om.user_id=auth.uid() and om.active=true)) with check (exists(select 1 from public.organization_members om where om.organization_id=expense_payments.organization_id and om.user_id=auth.uid() and om.active=true));